// Shared setup for the acceptance tests in this folder (work/spec.md).
// bun test runs every file in one process, so src/database reads SPOKE_DB only once.
// Each test gets its own in-memory copy of the seeded database, so no test sees another's writes.
import { Database } from "bun:sqlite";
import { tmpdir } from "node:os";
import { join } from "node:path";

process.env.SPOKE_DB ??= join(tmpdir(), `spoke-acceptance-${Date.now()}.db`);
process.env.SPOKE_LOG ??= join(tmpdir(), `spoke-acceptance-${Date.now()}.log`);

const { openDatabase } = await import("../../src/database");
export const { stationStatus, vehicleStatus } = await import("../../src/feed");
export const { recordWrench } = await import("../../src/wrenches");
export const { crewQueue } = await import("../../src/crew-queue");
export const { mapPage } = await import("../../src/map-page");

const seeded = openDatabase().serialize();

export const HOUR = 60 * 60 * 1000;

export function freshDatabase(): Database {
  return Database.deserialize(seeded);
}

export function count(database: Database, sql: string, ...params: string[]): number {
  return (database.query(sql).get(...params) as { n: number }).n;
}

export function bikeWith(database: Database, isDisabled: 0 | 1) {
  return database
    .query("SELECT bike_id, station_id FROM bikes WHERE is_disabled = ? ORDER BY bike_id LIMIT 1")
    .get(isDisabled) as { bike_id: string; station_id: string };
}

export function stationCounts(database: Database, stationId: string) {
  const station = stationStatus(database).data.stations.find((s) => s.station_id === stationId);
  if (!station) throw new Error(`station ${stationId} missing from station_status`);
  return station;
}

export function isDisabledInFeed(database: Database, bikeId: string): boolean | undefined {
  return vehicleStatus(database).data.vehicles.find((v) => v.vehicle_id === bikeId)?.is_disabled;
}

export function addOpenJob(
  database: Database,
  job: { job_id: string; depot: string; source: string; reported_at: Date; opened_at: Date },
) {
  database
    .query("INSERT INTO repair_jobs VALUES (?, 'B-1000', 'S-001', ?, ?, 'OTHER', ?, ?, NULL)")
    .run(
      job.job_id,
      job.depot,
      job.source,
      job.reported_at.toISOString(),
      job.opened_at.toISOString(),
    );
}

export function expectedDeadline(job: { source: string; reported_at: string }): string {
  const limit = job.source === "wrench" ? 48 : 96;
  return new Date(Date.parse(job.reported_at) + limit * HOUR).toISOString();
}

export function expectSortedByDeadline(
  jobs: { deadline: string; reported_at: string; job_id: string }[],
): boolean {
  for (let i = 1; i < jobs.length; i++) {
    const [a, b] = [jobs[i - 1], jobs[i]];
    const order =
      a.deadline.localeCompare(b.deadline) ||
      a.reported_at.localeCompare(b.reported_at) ||
      a.job_id.localeCompare(b.job_id);
    if (order > 0) return false;
  }
  return true;
}

