// AC-1. A wrench disables the bike in the vehicle feed at once (SLA-12, 0 seconds of grace).
import { expect, test } from "bun:test";
import { bikeWith, freshDatabase, isDisabledInFeed, recordWrench } from "./helpers";

test("AC-1: after a 201 wrench the very next vehicle feed shows the bike disabled", () => {
  const database = freshDatabase();
  const bike = bikeWith(database, 0);
  expect(isDisabledInFeed(database, bike.bike_id)).toBe(false);

  const outcome = recordWrench(database, { bike_id: bike.bike_id, fault: "BRAKES" });
  expect(outcome.status).toBe(201);

  expect(isDisabledInFeed(database, bike.bike_id)).toBe(true);
  const row = database.query("SELECT is_disabled FROM bikes WHERE bike_id = ?").get(bike.bike_id);
  expect(row).toEqual({ is_disabled: 1 });
});
EOF
cat > AC-2.test.ts <<'EOF'
// AC-2. The wrench, the repair job and the disabled flag are recorded together (all or nothing).
import { expect, test } from "bun:test";
import { bikeWith, count, freshDatabase, recordWrench } from "./helpers";

const WRENCHES = "SELECT COUNT(*) AS n FROM wrenches WHERE bike_id = ?";
const JOBS = "SELECT COUNT(*) AS n FROM repair_jobs WHERE bike_id = ?";
const WRENCH_JOBS =
  "SELECT COUNT(*) AS n FROM repair_jobs WHERE bike_id = ? AND source = 'wrench' AND closed_at IS NULL";
const DISABLED = "SELECT is_disabled AS n FROM bikes WHERE bike_id = ?";

test("AC-2: a 201 wrench adds exactly 1 wrench row, 1 open wrench job, and disables the bike", () => {
  const database = freshDatabase();
  const { bike_id } = bikeWith(database, 0);
  const wrenchesBefore = count(database, WRENCHES, bike_id);
  const jobsBefore = count(database, WRENCH_JOBS, bike_id);

  expect(recordWrench(database, { bike_id, fault: "CHAIN" }).status).toBe(201);

  expect(count(database, WRENCHES, bike_id)).toBe(wrenchesBefore + 1);
  expect(count(database, WRENCH_JOBS, bike_id)).toBe(jobsBefore + 1);
  expect(count(database, DISABLED, bike_id)).toBe(1);
});

// Each case makes one of the three writes fail with a trigger, then checks nothing was kept.
const failingWrites = [
  ["the wrenches insert", "BEFORE INSERT ON wrenches"],
  ["the repair_jobs insert", "BEFORE INSERT ON repair_jobs"],
  ["the bikes.is_disabled update", "BEFORE UPDATE ON bikes"],
] as const;

for (const [name, when] of failingWrites) {
  test(`AC-2: if ${name} fails, none of the three writes is kept`, () => {
    const database = freshDatabase();
    const { bike_id } = bikeWith(database, 0);
    const before = [WRENCHES, JOBS, DISABLED].map((sql) => count(database, sql, bike_id));
    database.exec(`CREATE TRIGGER fail_write ${when} BEGIN SELECT RAISE(ABORT, 'forced'); END`);

    let status: number | undefined;
    try {
      status = recordWrench(database, { bike_id, fault: "CHAIN" }).status;
    } catch {
      status = undefined; // a thrown error is an acceptable way to report the failure
    }

    expect(status).not.toBe(201);
    database.exec("DROP TRIGGER fail_write");
    const after = [WRENCHES, JOBS, DISABLED].map((sql) => count(database, sql, bike_id));
    expect(after).toEqual(before);
  });
}
EOF
