import { expect, test } from "bun:test";
import { join } from "node:path";
import { readCsv } from "../../src/csv";
import {
  HOUR, crewQueue, expectSortedByDeadline, expectedDeadline, freshDatabase,
} from "./helpers";

const seedJobs = readCsv(join(import.meta.dir, "..", "..", "data", "open-jobs.csv"));

test("AC-10: there are 40 seed jobs and the queue lists them all", () => {
