// AC-5. The map at / shows the same counts as station_status.json.
// The map draws each station's disabled count as a red badge and the fleet-wide
// available / disabled totals in its legend; it has no per-station available number.
import { expect, test } from "bun:test";
import { bikeWith, freshDatabase, mapPage, recordWrench, stationStatus } from "./helpers";

test("AC-5: after a wrench the map's badge and totals match station_status", () => {
  const database = freshDatabase();
  const bike = bikeWith(database, 0);
  expect(recordWrench(database, { bike_id: bike.bike_id, fault: "LOCK" }).status).toBe(201);

  const stations = stationStatus(database).data.stations;
  const html = mapPage(database);
  const feedStation = stations.find((s) => s.station_id === bike.station_id);
  if (!feedStation) throw new Error("station missing from feed");

  // The station's dot is followed by its red badge text when it has disabled bikes.
  const dot = new RegExp(
    `<title>${bike.station_id} [^<]*</title></circle>(?:<circle[^>]*fill="#dc2626"/><text[^>]*>(\\d+)</text>)?`,
  );
  const match = html.match(dot);
  expect(match).not.toBeNull();
  expect(Number(match?.[1] ?? 0)).toBe(feedStation.num_vehicles_disabled);

  const available = stations.reduce((sum, s) => sum + s.num_vehicles_available, 0);
  const disabled = stations.reduce((sum, s) => sum + s.num_vehicles_disabled, 0);
  expect(html).toContain(`<b>${available}</b> bikes riders can rent`);
  expect(html).toContain(`<b class="red">${disabled}</b> broken`);
});

