// AC-8. Deadlines count from the rider's report (SLA-4): reported_at + 48h wrench, + 96h other.
import { expect, test } from "bun:test";
import { HOUR, addOpenJob, crewQueue, expectedDeadline, freshDatabase } from "./helpers";

test("AC-8: every open job's deadline is reported_at + 48h (wrench) or + 96h (other)", () => {
  const database = freshDatabase();
  const now = Date.now();
  // Opened well after the report, so using opened_at would give a visibly different deadline.
  addOpenJob(database, {
    job_id: "J-AC8-W",
    depot: "South",
    source: "wrench",
    reported_at: new Date(now - 10 * HOUR),
    opened_at: new Date(now - 4 * HOUR),
  });
  addOpenJob(database, {
    job_id: "J-AC8-I",
    depot: "South",
    source: "inspection",
    reported_at: new Date(now - 30 * HOUR),
    opened_at: new Date(now - 20 * HOUR),
  });

  const jobs = crewQueue(database, null).jobs;
  expect(jobs.length).toBeGreaterThan(2);
  for (const job of jobs) {
    expect({ job: job.job_id, deadline: job.deadline }).toEqual({
      job: job.job_id,
      deadline: expectedDeadline(job),
    });
  }
  const wrench = jobs.find((j) => j.job_id === "J-AC8-W");
  expect(wrench?.deadline).toBe(new Date(now + 38 * HOUR).toISOString());
  const inspection = jobs.find((j) => j.job_id === "J-AC8-I");
  expect(inspection?.deadline).toBe(new Date(now + 66 * HOUR).toISOString());
});

