// AC-9. The job due first is on top: deadline asc, then reported_at asc, then job_id.
import { expect, test } from "bun:test";
import { HOUR, addOpenJob, crewQueue, expectSortedByDeadline, freshDatabase } from "./helpers";

function databaseWithTies() {
  const database = freshDatabase();
  const base = Date.now() - 2 * HOUR;
  // Same deadline (base + 48h): a wrench reported at base, and an inspection reported 48h earlier.
  // The tie is broken by reported_at, so the inspection comes first.
  addOpenJob(database, {
    job_id: "J-AC9-A",
    depot: "North",
    source: "wrench",
    reported_at: new Date(base),
    opened_at: new Date(base + 0.5 * HOUR),
  });
  addOpenJob(database, {
    job_id: "J-AC9-B",
    depot: "North",
    source: "inspection",
    reported_at: new Date(base - 48 * HOUR),
    opened_at: new Date(base + 1 * HOUR),
  });
  // Same deadline and reported_at as J-AC9-A: the tie is broken by job_id.
  addOpenJob(database, {
    job_id: "J-AC9-0",
    depot: "North",
    source: "wrench",
    reported_at: new Date(base),
    opened_at: new Date(base + 0.9 * HOUR),
  });
  return database;
}

test("AC-9: the full queue is sorted by deadline, then reported_at, then job_id", () => {
  const jobs = crewQueue(databaseWithTies(), null).jobs;
  expect(jobs.length).toBeGreaterThanOrEqual(2);
  expect(expectSortedByDeadline(jobs)).toBe(true);
});

test("AC-9: jobs[0] has the earliest deadline", () => {
  const jobs = crewQueue(databaseWithTies(), null).jobs;
  const earliest = jobs.map((j) => j.deadline).sort()[0];
  expect(jobs[0].deadline).toBe(earliest);
});

test("AC-9: equal deadlines are ordered by reported_at, then job_id", () => {
  const ids = crewQueue(databaseWithTies(), "North")
    .jobs.map((j) => j.job_id)
    .filter((id) => id.startsWith("J-AC9-"));
  expect(ids).toEqual(["J-AC9-B", "J-AC9-0", "J-AC9-A"]);
});

test("AC-9: the depot-filtered queue follows the same order", () => {
  const jobs = crewQueue(databaseWithTies(), "North").jobs;
  expect(jobs.length).toBeGreaterThanOrEqual(2);
  expect(expectSortedByDeadline(jobs)).toBe(true);
});

