// AC-10. Jobs already open at launch (the 40 seed jobs) follow the contract.
import { expect, test } from "bun:test";
import { join } from "node:path";
import { readCsv } from "../../src/csv";
import {
  HOUR,
  crewQueue,
  expectSortedByDeadline,
  expectedDeadline,
  freshDatabase,
} from "./helpers";

const seedJobs = readCsv(join(import.meta.dir, "..", "..", "data", "open-jobs.csv"));

test("AC-10: there are 40 seed jobs and the queue lists them all", () => {
  expect(seedJobs).toHaveLength(40);
  const ids = crewQueue(freshDatabase(), null).jobs.map((j) => j.job_id);
  for (const job of seedJobs) expect(ids).toContain(job.job_id);
});

test("AC-10: each seed deadline is reported_at + limit, earlier by its 0.1h to 1.0h gap", () => {
  const jobs = crewQueue(freshDatabase(), null).jobs;
  for (const seed of seedJobs) {
    const job = jobs.find((j) => j.job_id === seed.job_id);
    if (!job) throw new Error(`${seed.job_id} missing from queue`);
    expect({ job: job.job_id, deadline: job.deadline }).toEqual({
      job: job.job_id,
      deadline: expectedDeadline(job),
    });

    const limit = (job.source === "wrench" ? 48 : 96) * HOUR;
    const movedEarlierBy = Date.parse(job.opened_at) + limit - Date.parse(job.deadline);
    const gap = (Number(seed.reported_hours_ago) - Number(seed.opened_hours_ago)) * HOUR;
    expect(gap).toBeGreaterThanOrEqual(0.1 * HOUR - 1);
    expect(gap).toBeLessThanOrEqual(1.0 * HOUR + 1);
    expect(Math.abs(movedEarlierBy - gap)).toBeLessThan(1000);
  }
});

test("AC-10: 0 seed jobs are overdue at launch", () => {
  const now = Date.now();
  const overdue = crewQueue(freshDatabase(), null).jobs.filter(
    (j) => Date.parse(j.deadline) <= now,
  );
  expect(overdue.map((j) => j.job_id)).toEqual([]);
});

test("AC-10: seed jobs are ordered by AC-9", () => {
  expect(expectSortedByDeadline(crewQueue(freshDatabase(), null).jobs)).toBe(true);
});

